ctionData\":{\"description\":\"Time-series-backed variant of `LinearFunctionData`. In place of inline coefficients it carries `association_id`, referencing a stored series that supplies them at each step; use it when the coefficients change over time.\",\"properties\":{\"function_type\":{\"const\":\"TIME_SERIES_LINEAR\",\"type\":\"string\",\"default\":\"TIME_SERIES_LINEAR\"},\"association_id\":{\"type\":\"integer\",\"description\":\"Store-minted id of the time series association whose values supply this function data over time. Resolved against the accompanying time series store on read; minted by that store and meaningful only against it, never assigned by a document producer.\"}},\"required\":[\"function_type\",\"association_id\"],\"title\":\"TimeSeriesLinearFunctionData\",\"type\":\"object\"},\"TimeSeriesPiecewiseLinearData\":{\"description\":\"Time-series-backed variant of `PiecewiseLinearData`. In place of an inline point table it carries `association_id`, referencing a stored series that supplies one at each step; use it when the points change over time.\",\"properties\":{\"function_type\":{\"const\":\"TIME_SERIES_PIECEWISE_LINEAR\",\"type\":\"string\",\"default\":\"TIME_SERIES_PIECEWISE_LINEAR\"},\"association_id\":{\"type\":\"integer\",\"description\":\"Store-minted id of the time series association whose values supply this function data over time. Resolved against the accompanying time series store on read; minted by that store and meaningful only against it, never assigned by a document producer.\"}},\"required\":[\"function_type\",\"association_id\"],\"title\":\"TimeSeriesPiecewiseLinearData\",\"type\":\"object\"},\"TimeSeriesPiecewiseStepData\":{\"description\":\"Time-series-backed variant of `PiecewiseStepData`. In place of inline coordinate vectors it carries `association_id`, referencing a stored series that supplies them at each step; use it when the segments change over time.\",\"properties\":{\"function_type\":{\"const\":\"TIME_SERIES_PIECEWISE_STE